409	export scope PromptEditor:
410	    concept: {PromptEditorConcept}
411	
412	concept PromptEditorConcept:
413	    pitch:
414	        A chat-style interface for prompting a local coding harness like Claude
415	        Code directly with compiled-on-depand Piton.
416	
417	    shape: {PromptEditorShape}
418	
419	shape PromptEditorShape:
420	    description:
421	        Typical AI-style chat interface.
422	
423	    basicDesignAndLayout:
424	        Chat history fills that all available space except for a
425	        @{ChatInputScope} along the bottom.
426	
427	    chatHistory: @{MessageList}
428	
429	    pinnedHeader:
430	        While the harness is working, the prompt it is working on is pinned as
431	        a header along the top of the chat history, and the conversation
432	        scrolls beneath it. It shows up to three lines of the prompt beside a
433	        spinner, and clicking it scrolls the conversation to that prompt.
434	
435	        The queue sits in the same header as an expanding list: a row saying
436	        how many prompts are queued, with a chevron, expands to list each
437	        queued prompt in order, a line or two of each, with a button to cancel
438	        it. The header also holds the auto-send switch and the "Send next"
439	        button. The queue row, with its switch and button, is shown only while
