820	    /// Replaces the queue with the one saved for the current project. A
821	    /// restored queue waits to be sent.
822	    fn load_queue(&mut self, cx: &mut Context<Self>) {
823	        let saved = ProjectDirectory::get(cx)
824	            .map(|project_dir| prompt_queue::load(&project_dir))
825	            .unwrap_or_default();
826	        self.queue = saved
827	            .into_iter()
828	            .map(|saved| {
829	                self.next_queue_id += 1;
830	                QueueItem {
831	                    id: self.next_queue_id,
832	                    text: saved.text.clone().into(),
833	                    saved: Some(saved),
834	                }
835	            })
836	            .collect();
837	        self.queue_held = !self.queue.is_empty();
