841	    /// Replaces the tasks with those sent before in the current project, read
842	    /// in the background. Tasks are only replaced while the harness is free,
843	    /// so a run's task keeps its index; otherwise the history loads once the
844	    /// run is over, the run's own task among it.
845	    fn load_history(&mut self, cx: &mut Context<Self>) {
846	        if self.working {
847	            self.history_stale = true;
848	            return;
849	        }
850	        self.history_stale = false;
851	        let Some(project_dir) = ProjectDirectory::get(cx) else {
852	            self._history_load = Task::ready(());
853	            return;
854	        };
855	        let load = cx.background_spawn(async move {
856	            prompt_history::load(&project_dir)
857	                .into_iter()
858	                .map(PromptTask::restore)
859	                .collect::<Vec<_>>()
860	        });
861	        self._history_load = cx.spawn(async move |this, cx| {
862	            let tasks = load.await;
863	            this.update(cx, |this, cx| {
864	                if this.working {
865	                    this.history_stale = true;
866	                    return;
867	                }
868	                this.tasks = tasks;
869	                this.open_task = None;
870	                this.output_scroll.set_offset(point(px(0.), px(0.)));
871	                cx.notify();
872	            })
873	            .ok();
874	        });
875	    }
