885	    /// Adds `text` to the end of the queue, then resolves its hidden anchor,
886	    /// with the system prompt of `mode`, and saves it with the project in the
887	    /// background.
888	    fn enqueue(
889	        &mut self,
890	        text: String,
891	        mode: SendMode,
892	        window: &mut Window,
893	        cx: &mut Context<Self>,
894	    ) {
895	        let Some(project_dir) = ProjectDirectory::get(cx) else {
896	            return;
897	        };
898	        self.next_queue_id += 1;
899	        let id = self.next_queue_id;
900	        self.queue.push(QueueItem {
901	            id,
902	            text: text.clone().into(),
903	            saved: None,
904	        });
905	        cx.notify();
906	
907	        let lsp = self.chat_input.read(cx).lsp();
908	        let save = cx.background_spawn({
909	            let project_dir = project_dir.clone();
910	            async move {
911	                let anchor = resolve_anchor(&text, mode, lsp, &project_dir)?;
912	                prompt_queue::add(anchor, text, &project_dir)
913	            }
914	        });
915	        cx.spawn_in(window, async move |this, cx| {
916	            let saved = save.await;
917	            this.update_in(cx, |this, window, cx| {
918	                this.queue_saved(id, saved, &project_dir, window, cx)
919	            })
920	            .ok();
921	        })
922	        .detach();
923	    }
