925	    fn queue_saved(
926	        &mut self,
927	        id: usize,
928	        saved: Result<QueuedPrompt>,
929	        project_dir: &std::path::Path,
930	        window: &mut Window,
931	        cx: &mut Context<Self>,
932	    ) {
933	        let Some(ix) = self.queue.iter().position(|item| item.id == id) else {
934	            // Cancelled while it was saved. A queue left behind by switching
935	            // projects keeps it, for when that project is opened again.
936	            if let Ok(saved) = saved
937	                && ProjectDirectory::get(cx).as_deref() == Some(project_dir)
938	            {
939	                prompt_queue::remove(&saved.file).ok();
940	            }
941	            return;
942	        };
943	        match saved {
944	            Ok(saved) => {
945	                self.queue[ix].saved = Some(saved);
946	                self.auto_send_next(cx);
947	            }
948	            Err(err) => {
949	                self.queue.remove(ix);
950	                window.push_notification(
951	                    Notification::error(format!("{err:#}")).title("Could not queue the prompt"),
952	                    cx,
953	                );
954	            }
955	        }
956	        cx.notify();
957	    }
