959	    /// Sends the first queued prompt, if the harness is free and it is saved.
960	    fn send_next(&mut self, cx: &mut Context<Self>) {
961	        // Without a project it could not be sent, and must stay queued.
962	        if self.working
963	            || ProjectDirectory::get(cx).is_none()
964	            || !self.queue.first().is_some_and(|item| item.saved.is_some())
965	        {
966	            return;
967	        }
968	        let item = self.queue.remove(0);
969	        if self.queue.is_empty() {
970	            self.queue_held = false;
971	        }
972	        let Some(saved) = item.saved else { return };
973	        self.start(item.text.to_string(), Sending::Queued(saved), cx);
974	    }
