983	    /// Removes a prompt that has not been sent from the queue, and its file.
984	    fn cancel(&mut self, id: usize, window: &mut Window, cx: &mut Context<Self>) {
985	        let Some(ix) = self.queue.iter().position(|item| item.id == id) else {
986	            return;
987	        };
988	        let item = self.queue.remove(ix);
989	        if let Some(saved) = &item.saved
990	            && let Err(err) = prompt_queue::remove(&saved.file)
991	        {
992	            // Its file is still there, so it is still queued.
993	            self.queue.insert(ix, item);
994	            window.push_notification(
995	                Notification::error(format!("{err:#}")).title("Could not cancel the prompt"),
996	                cx,
997	            );
998	        }
999	        if self.queue.is_empty() {
1000	            self.queue_held = false;
1001	        }
1002	        cx.notify();
1003	    }
