1023	    /// Sends `text` to the harness as a new task: a queued prompt with the
1024	    /// anchor it was saved with, else with a freshly resolved one.
1025	    fn start(&mut self, text: String, sending: Sending, cx: &mut Context<Self>) {
1026	        let Some(project_dir) = ProjectDirectory::get(cx) else {
1027	            return;
1028	        };
1029	        let task_ix = self.push_task(text.clone().into(), cx);
1030	        self.working = true;
1031	        self.chat_input
1032	            .update(cx, |input, cx| input.set_busy(true, cx));
1033	
1034	        let lsp = self.chat_input.read(cx).lsp();
1035	        let compile = cx.background_spawn({
1036	            let project_dir = project_dir.clone();
1037	            async move {
1038	                let anchor = match sending {
1039	                    // Out of the queue first, so it is never sent twice.
1040	                    Sending::Queued(queued) => {
1041	                        prompt_queue::remove(&queued.file)?;
1042	                        queued.anchor
1043	                    }
1044	                    Sending::Now(mode) => resolve_anchor(&text, mode, lsp, &project_dir)?,
1045	                };
1046	                let file = hidden_anchor::save(&anchor, &text, &project_dir)?;
1047	                let compiled = hidden_anchor::compile(&anchor, &file, &project_dir);
1048	                anyhow::Ok((anchor.name().to_string(), file, compiled))
1049	            }
1050	        });
1051	
1052	        self._pending = cx.spawn(async move |this, cx| {
1053	            // What came of the prompt, saved beside it in the history once it
1054	            // is over.
1055	            let mut record = RunRecord::default();
1056	            let mut prompt_file = None;
1057	            let compiled = compile.await.and_then(|(anchor, file, compiled)| {
1058	                prompt_file = Some(file);
1059	                Ok((anchor, compiled?))
1060	            });
1061	            match compiled {
1062	                Ok((anchor, compiled)) => {
1063	                    let prompt = compiled.user_prompt;
1064	                    record.user_prompt = Some(prompt.clone());
1065	                    let mut events =
1066	                        harness::send(prompt.clone(), compiled.system_prompt, project_dir);
1067	                    if this
1068	                        .update(cx, |this, cx| {
1069	                            this.show_compiled(task_ix, anchor, prompt, cx)
1070	                        })
1071	                        .is_err()
1072	                    {
1073	                        return;
1074	                    }
1075	                    while let Some(event) = events.next().await {
1076	                        record.note(&event);
1077	                        if this
1078	                            .update(cx, |this, cx| this.apply_event(task_ix, event, cx))
1079	                            .is_err()
1080	                        {
1081	                            return;
1082	                        }
1083	                    }
1084	                }
1085	                Err(err) => {
1086	                    let error = format!("{err:#}");
1087	                    record.error = Some(error.clone());
1088	                    this.update(cx, |this, _| {
1089	                        if let Some(task) = this.tasks.get_mut(task_ix) {
1090	                            task.fail(error);
1091	                        }
1092	                    })
1093	                    .ok();
1094	                }
1095	            }
1096	
1097	            // Unsaved (the prompt itself could not be saved) there is nothing
1098	            // to save it beside.
1099	            let saved = match prompt_file {
1100	                Some(file) => {
1101	                    cx.background_spawn(async move { prompt_history::save_record(&file, &record) })
1102	                        .await
1103	                }
1104	                None => Ok(()),
1105	            };
1106	
1107	            this.update(cx, |this, cx| {
1108	                if let Some(task) = this.tasks.get_mut(task_ix) {
1109	                    task.end();
1110	                    if let Err(err) = saved {
1111	                        // Shown without failing the task: the run itself is
1112	                        // unaffected.
1113	                        task.reply.parts.push(ReplyPart::Error(format!(
1114	                            "Could not save this task to the history: {err:#}"
1115	                        )));
1116	                    }
1117	                }
1118	                this.working = false;
1119	                if this.history_stale {
1120	                    this.load_history(cx);
1121	                }
1122	                this.chat_input
1123	                    .update(cx, |input, cx| input.set_busy(false, cx));
1124	                // Deferred: starting the next run replaces this task.
1125	                let prompt_mode = cx.entity();
1126	                cx.defer(move |cx| prompt_mode.update(cx, |this, cx| this.auto_send_next(cx)));
1127	                cx.notify();
1128	            })
1129	            .ok();
1130	        });
1131	    }
1132	
1133	    /// Asks `text` straight away, beside any task the harness is working on,
1134	    /// in place of any question still open. It is saved apart from the
1135	    /// history, so it never becomes one of the tasks.
1136	    fn ask(&mut self, text: String, cx: &mut Context<Self>) {
1137	        let Some(project_dir) = ProjectDirectory::get(cx) else {
1138	            return;
1139	        };
1140	        let run = self.push_ask(text.clone().into(), cx);
1141	        let lsp = self.chat_input.read(cx).lsp();
1142	        let compile = cx.background_spawn({
1143	            let project_dir = project_dir.clone();
1144	            async move {
1145	                let anchor = resolve_anchor(&text, SendMode::Ask, lsp, &project_dir)?;
1146	                let file = hidden_anchor::save_ask(&anchor, &text, &project_dir)?;
1147	                let compiled = hidden_anchor::compile(&anchor, &file, &project_dir)?;
1148	                anyhow::Ok((anchor.name().to_string(), compiled))
1149	            }
1150	        });
1151	
1152	        // Replacing the run drops any earlier question's, which stops it.
1153	        self._ask_pending = cx.spawn(async move |this, cx| {
1154	            match compile.await {
1155	                Ok((anchor, compiled)) => {
1156	                    let prompt = compiled.user_prompt;
1157	                    let mut events =
1158	                        harness::send(prompt.clone(), compiled.system_prompt, project_dir);
1159	                    let compiled = Compiled {
1160	                        anchor: anchor.into(),
1161	                        markdown: prompt,
1162	                    };
1163	                    if this
1164	                        .update(cx, |this, cx| {
1165	                            this.update_ask(run, |ask| ask.set_compiled(compiled), cx)
1166	                        })
1167	                        .is_err()
1168	                    {
1169	                        return;
1170	                    }
1171	                    while let Some(event) = events.next().await {
1172	                        if this
1173	                            .update(cx, |this, cx| this.update_ask(run, |ask| ask.apply(event), cx))
1174	                            .is_err()
1175	                        {
1176	                            return;
1177	                        }
1178	                    }
1179	                }
1180	                Err(err) => {
1181	                    this.update(cx, |this, cx| {
1182	                        this.update_ask(run, |ask| ask.fail(format!("{err:#}")), cx)
1183	                    })
1184	                    .ok();
1185	                }
1186	            }
1187	            this.update(cx, |this, cx| this.update_ask(run, PromptTask::end, cx))
1188	                .ok();
1189	        });
1190	    }
