//! The prompt history on disk. Each sent prompt is saved in the project's
//! `.suspense/history` as its hidden anchor's source (see
//! [`crate::hidden_anchor::save`]). Once its run is over, what came of it is
//! saved beside it in a `.json` file of the same name: the compiled prompt the
//! harness received, the harness's output line by line, and any error. Opening
//! the project again replays them into the tasks they were.

use std::fs;
use std::path::{Path, PathBuf};

use anyhow::{Context as _, Result};
use serde::{Deserialize, Serialize};
use serde_json::Value;

use crate::harness::HarnessEvent;
use crate::hidden_anchor::{self, HiddenAnchor};

/// What came of a sent prompt, as saved beside it.
#[derive(Debug, Default, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RunRecord {
    /// The compiled `userPrompt` the harness received; none if the prompt did
    /// not compile.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub user_prompt: Option<String>,
    /// Each line the harness printed, as JSON where it was, else as a string.
    #[serde(default)]
    pub output: Vec<Value>,
    /// Why the run failed, when the harness's output does not say.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub error: Option<String>,
}

impl RunRecord {
    /// Keeps what of a harness event cannot be replayed from its output: the
    /// raw lines themselves, and a failure outside them.
    pub fn note(&mut self, event: &HarnessEvent) {
        match event {
            HarnessEvent::Output(line) => self
                .output
                .push(serde_json::from_str(line).unwrap_or_else(|_| Value::String(line.clone()))),
            HarnessEvent::Failed(error) => self.error = Some(error.clone()),
            _ => {}
        }
    }
}

/// A prompt in the history, and its run's record if one was saved.
pub struct SavedPrompt {
    pub anchor: HiddenAnchor,
    pub text: String,
    pub record: Option<RunRecord>,
}

/// The record file saved beside `prompt_file`.
fn record_path(prompt_file: &Path) -> PathBuf {
    prompt_file.with_extension("json")
}

/// Saves `record` beside the history file of the prompt it came of.
pub fn save_record(prompt_file: &Path, record: &RunRecord) -> Result<()> {
    let file = record_path(prompt_file);
    let json = serde_json::to_string_pretty(record)?;
    fs::write(&file, json).with_context(|| format!("could not save {}", file.display()))
}

/// The project's prompt history, oldest first. Files that do not read back as
/// a hidden anchor are left out; a record that is missing or does not read
/// back is `None`.
pub fn load(project_dir: &Path) -> Vec<SavedPrompt> {
    let Ok(entries) = fs::read_dir(hidden_anchor::history_dir(project_dir)) else {
        return Vec::new();
    };
    let mut files: Vec<(u64, PathBuf)> = entries
        .filter_map(|entry| Some(entry.ok()?.path()))
        .filter(|path| path.extension().is_some_and(|ext| ext == "pi"))
        .map(|path| (sent_at(&path), path))
        .collect();
    files.sort();
    files
        .into_iter()
        .filter_map(|(_, file)| {
            let (anchor, text) = HiddenAnchor::parse(&fs::read_to_string(&file).ok()?)?;
            let record = fs::read_to_string(record_path(&file))
                .ok()
                .and_then(|json| serde_json::from_str(&json).ok());
            Some(SavedPrompt {
                anchor,
                text,
                record,
            })
        })
        .collect()
}

/// When a history file was sent, from the seconds its name starts with. Not
/// zero-padded, so compared as numbers rather than names.
fn sent_at(file: &Path) -> u64 {
    file.file_name()
        .and_then(|name| name.to_str()?.split_once('-')?.0.parse().ok())
        .unwrap_or(0)
}

#[cfg(test)]
mod tests {
    use std::fs;
    use std::path::Path;

    use super::{RunRecord, load, save_record};
    use crate::harness::HarnessEvent;
    use crate::hidden_anchor::{self, HiddenAnchor};

    /// A saved prompt loads back with the record saved beside it; one without
    /// a record loads back without one.
    #[test]
    fn prompts_load_back_with_their_records() {
        let project_dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("target/prompt-history-test");
        fs::remove_dir_all(&project_dir).ok();

        let recorded = HiddenAnchor::random();
        let file = hidden_anchor::save(&recorded, "recorded", &project_dir).unwrap();
        let mut record = RunRecord {
            user_prompt: Some("recorded, compiled".into()),
            ..RunRecord::default()
        };
        for event in [
            HarnessEvent::Output(r#"{"type":"result","result":"ok"}"#.into()),
            HarnessEvent::Output("not json".into()),
            HarnessEvent::TextDelta("parsed, not kept".into()),
            HarnessEvent::Failed("it broke".into()),
        ] {
            record.note(&event);
        }
        save_record(&file, &record).unwrap();

        let history = load(&project_dir);
        assert_eq!(history.len(), 1);
        assert_eq!(history[0].anchor.name(), recorded.name());
        assert_eq!(history[0].text, "recorded");
        assert_eq!(history[0].record.as_ref(), Some(&record));
        assert_eq!(
            record.output,
            [
                serde_json::json!({ "type": "result", "result": "ok" }),
                serde_json::json!("not json"),
            ]
        );

        fs::remove_file(file.with_extension("json")).unwrap();
        assert!(load(&project_dir)[0].record.is_none());
    }
}
//! The hidden anchor. Prompts are typed as plain text, but behind the scenes
//! they are the `userPrompt` of a randomly-named Piton anchor whose imports
//! `piton lsp` adds automatically (see [`crate::piton_lsp`]), so they are never
//! written or seen. Each sent prompt is saved as a `.pi` file in the project's
//! prompt history and compiled; the compiled `userPrompt` is what the harness
//! receives.

use std::collections::{BTreeMap, BTreeSet};
use std::fmt::Write as _;
use std::fs;
use std::hash::{BuildHasher, RandomState};
use std::path::{Path, PathBuf};
use std::process::Command;
use std::time::{SystemTime, UNIX_EPOCH};

use anyhow::{Context as _, Result, anyhow};
use serde_json::Value;

use crate::chat_input::SendMode;
use crate::project_directory::CONFIG_FILE_NAME;

/// Indentation of each prompt line inside the anchor's `userPrompt` block.
pub const PROMPT_INDENT: &str = "        ";

/// Where the application keeps its files, relative to the project directory.
pub const APP_DIR: &str = ".suspense";
const HISTORY_DIR: &str = "history";
/// Where questions asked from the Ask tab are saved, apart from the history.
const ASKS_DIR: &str = "asks";

/// The hidden anchor's imports: names by module.
#[derive(Clone, Debug, Default)]
pub struct Imports(BTreeMap<String, BTreeSet<String>>);

impl Imports {
    /// Adds the names of every `from <module> import A, B` line in `source`,
    /// ignoring other lines. Returns whether any name was new.
    pub fn add_from_source(&mut self, source: &str) -> bool {
        let mut added = false;
        for line in source.lines() {
            let Some((module, names)) = line
                .trim()
                .strip_prefix("from ")
                .and_then(|rest| rest.split_once(" import "))
            else {
                continue;
            };
            let names: Vec<&str> = names
                .split(',')
                .map(str::trim)
                .filter(|name| !name.is_empty())
                .collect();
            if names.is_empty() {
                continue;
            }
            let imported = self.0.entry(absolute_module(module.trim())).or_default();
            for name in names {
                added |= imported.insert(name.to_string());
            }
        }
    }
}

/// The system prompt a prompt sent in `mode` is given, naming the code and
/// spec locations set in the project's `piton.config.pi`.
pub fn system_prompt(mode: SendMode, project_dir: &Path) -> Result<String> {
    let code = config_value(project_dir, "codeRoot")?;
    let spec = config_value(project_dir, "root")?;
    Ok(match mode {
        SendMode::Code => format!(
            "We're working on the code located in {code}. Don't edit the spec located in {spec}."
        ),
        SendMode::Both => format!(
            "We're working on both the code located in {code} and the spec located in {spec}. Edit both of them."
        ),
        SendMode::Spec => format!(
            "We're working on the spec located in {spec}. Don't edit the code located in {code}."
        ),
        SendMode::Ask => format!(
            "We're only asking a question about the code located in {code} and the spec located in {spec}. Don't edit either of them."
        ),
    })
}

/// The path the chat input's unsent text is presented to `piton lsp` under.
/// Nothing is written there. It sits inside the spec root because `piton lsp`
/// only resolves imports, and offers auto-imports, for documents under it.
pub fn draft_path(project_dir: &Path) -> PathBuf {
    let spec_root = spec_root(project_dir).unwrap_or_default();
    project_dir.join(spec_root).join(".suspense-draft.pi")
}

/// The project's prompt history directory.
pub fn history_dir(project_dir: &Path) -> PathBuf {
    project_dir.join(APP_DIR).join(HISTORY_DIR)
}

/// Saves `prompt`, as `anchor`'s source, to the project's prompt history.
pub fn save(anchor: &HiddenAnchor, prompt: &str, project_dir: &Path) -> Result<PathBuf> {
    save_in(&history_dir(project_dir), anchor, prompt)
}

/// Saves a question, as `anchor`'s source, where it can be compiled without
/// joining the prompt history.
pub fn save_ask(anchor: &HiddenAnchor, prompt: &str, project_dir: &Path) -> Result<PathBuf> {
    save_in(&project_dir.join(APP_DIR).join(ASKS_DIR), anchor, prompt)
}

fn save_in(dir: &Path, anchor: &HiddenAnchor, prompt: &str) -> Result<PathBuf> {
    fs::create_dir_all(dir).with_context(|| format!("could not create {}", dir.display()))?;
    let sent_at = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_or(0, |elapsed| elapsed.as_secs());
    let file = dir.join(format!("{sent_at}-{}.pi", anchor.name));
    fs::write(&file, anchor.source(prompt))
        .with_context(|| format!("could not save {}", file.display()))?;
    Ok(file)
}

/// Compiles `file`, a saved `anchor`, and returns its compiled prompt text.
pub fn compile(anchor: &HiddenAnchor, file: &Path, project_dir: &Path) -> Result<CompiledPrompt> {
    let output = Command::new("piton")
        .args(["compile", "--stdout"])
        .arg(file)
        .current_dir(project_dir)
        .output()
        .context("could not run `piton compile`")?;
    if !output.status.success() {
        let mut message = String::from_utf8_lossy(&output.stdout).into_owned();
        message.push_str(&String::from_utf8_lossy(&output.stderr));
        return Err(anyhow!("{}", message.trim()));
    }

    let compiled: Value =
        serde_json::from_slice(&output.stdout).context("`piton compile` did not print JSON")?;
    let compiled = compiled
        .get(&anchor.name)
        .ok_or_else(|| anyhow!("the compiled output has no {}", anchor.name))?;
    let user_prompt = compiled
        .get("userPrompt")
        .ok_or_else(|| anyhow!("the compiled anchor has no userPrompt"))?;
    Ok(CompiledPrompt {
        user_prompt: prose(user_prompt),
        system_prompt: compiled.get("systemPrompt").map(prose),
    })
}

